package crdt

import (
	"encoding/json"
	"math/rand"
	"os"
	"strings"
	"testing"
)

type vectorFile struct {
	Vectors []struct {
		Name        string `json:"name"`
		Ops         []Op   `json:"ops"`
		Text        string `json:"text"`
		Fingerprint string `json:"fingerprint"`
	} `json:"vectors"`
}

func applyAll(t *testing.T, d *Document, ops []Op) {
	t.Helper()
	for _, op := range ops {
		if _, err := d.Apply(op); err != nil {
			t.Fatalf("apply %+v: %v", op, err)
		}
	}
}

// TestVectorsMatchTypeScript replays vectors generated by the TypeScript
// implementation in several delivery orders. Matching text and fingerprints
// prove the Go and TypeScript replicas converge to identical state.
func TestVectorsMatchTypeScript(t *testing.T) {
	raw, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var vf vectorFile
	if err := json.Unmarshal(raw, &vf); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	if len(vf.Vectors) < 40 {
		t.Fatalf("expected at least 40 vectors, got %d", len(vf.Vectors))
	}
	for _, v := range vf.Vectors {
		v := v
		t.Run(v.Name, func(t *testing.T) {
			orders := [][]Op{v.Ops, reversed(v.Ops)}
			for seed := int64(1); seed <= 5; seed++ {
				orders = append(orders, shuffled(v.Ops, seed))
			}
			for i, ops := range orders {
				d := NewDocument(Limits{})
				applyAll(t, d, ops)
				if d.Pending() != 0 {
					t.Fatalf("order %d: %d ops still buffered", i, d.Pending())
				}
				if got := d.Text(); got != v.Text {
					t.Fatalf("order %d: text %q, want %q", i, got, v.Text)
				}
				if got := d.Fingerprint(); got != v.Fingerprint {
					t.Fatalf("order %d: fingerprint mismatch", i)
				}
			}
		})
	}
}

func reversed(ops []Op) []Op {
	out := make([]Op, len(ops))
	for i, op := range ops {
		out[len(ops)-1-i] = op
	}
	return out
}

func shuffled(ops []Op, seed int64) []Op {
	out := append([]Op(nil), ops...)
	r := rand.New(rand.NewSource(seed))
	r.Shuffle(len(out), func(i, j int) { out[i], out[j] = out[j], out[i] })
	return out
}

func insertAt(t *testing.T, d *Document, client string, pos int, text string) []Op {
	t.Helper()
	var after *ID
	if pos > 0 {
		ids := d.VisibleIDs()
		id := ids[pos-1]
		after = &id
	}
	ops, err := d.InsertText(client, after, text)
	if err != nil {
		t.Fatalf("insert: %v", err)
	}
	return ops
}

// Regression test for issue R1: positions must not collapse after long typing runs.
func TestSequentialTypingThenMidInsert(t *testing.T) {
	d := NewDocument(Limits{})
	text := strings.Repeat("The quick brown fox jumps over the lazy dog. ", 223)[:10000]
	var last *ID
	for _, r := range text {
		ops, err := d.InsertText("alice", last, string(r))
		if err != nil {
			t.Fatal(err)
		}
		id := ops[0].ID
		last = &id
	}
	insertAt(t, d, "alice", 70, "#")
	want := text[:70] + "#" + text[70:]
	if d.Text() != want {
		t.Fatalf("mid insert landed in the wrong place")
	}
}

// Regression test for issue R2: a delete must remove exactly the targeted character.
func TestConcurrentInsertDeleteOwn(t *testing.T) {
	a, b := NewDocument(Limits{}), NewDocument(Limits{})
	oa, _ := a.InsertText("alice", nil, "A")
	ob, _ := b.InsertText("bob", nil, "B")
	applyAll(t, a, ob)
	applyAll(t, b, oa)
	del := b.DeleteIDs([]ID{ob[0].ID})
	applyAll(t, a, del)
	if a.Text() != "A" || b.Text() != "A" || a.Fingerprint() != b.Fingerprint() {
		t.Fatalf("diverged: a=%q b=%q", a.Text(), b.Text())
	}
}

func TestDuplicateAndOutOfOrderDelivery(t *testing.T) {
	src := NewDocument(Limits{})
	ops := insertAt(t, src, "a", 0, "abcdef")
	ops = append(ops, src.DeleteIDs(src.VisibleIDs()[2:4])...)
	dst := NewDocument(Limits{})
	rev := reversed(ops)
	st, err := dst.Apply(rev[0])
	if err != nil || st != Buffered {
		t.Fatalf("delete of unknown atom should buffer, got %v %v", st, err)
	}
	applyAll(t, dst, rev[1:])
	applyAll(t, dst, ops) // duplicates
	if dst.Text() != "abef" || dst.Pending() != 0 || dst.Fingerprint() != src.Fingerprint() {
		t.Fatalf("got %q pending=%d", dst.Text(), dst.Pending())
	}
}

func TestValidation(t *testing.T) {
	origin := ID{C: "b", T: 5}
	cases := []struct {
		name string
		op   Op
	}{
		{"unknown kind", Op{K: "x", ID: ID{C: "a", T: 1}}},
		{"empty client", Op{K: "d", ID: ID{C: "", T: 1}}},
		{"bad client chars", Op{K: "i", ID: ID{C: "a b", T: 1}, V: "x"}},
		{"zero counter", Op{K: "i", ID: ID{C: "a", T: 0}, V: "x"}},
		{"counter beyond 2^53", Op{K: "i", ID: ID{C: "a", T: MaxT + 1}, V: "x"}},
		{"two code points", Op{K: "i", ID: ID{C: "a", T: 1}, V: "ab"}},
		{"empty value", Op{K: "i", ID: ID{C: "a", T: 1}, V: ""}},
		{"invalid utf8", Op{K: "i", ID: ID{C: "a", T: 1}, V: "\xff"}},
		{"origin not older", Op{K: "i", ID: ID{C: "a", T: 5}, O: &origin, V: "x"}},
	}
	for _, c := range cases {
		if err := ValidateOp(c.op); err == nil {
			t.Errorf("%s: expected validation error", c.name)
		}
		d := NewDocument(Limits{})
		if _, err := d.Apply(c.op); err == nil {
			t.Errorf("%s: Apply accepted invalid op", c.name)
		}
	}
	d := NewDocument(Limits{})
	if _, err := d.Apply(Op{K: "i", ID: ID{C: "a", T: 1}, V: "x"}); err != nil {
		t.Fatal(err)
	}
	if _, err := d.Apply(Op{K: "i", ID: ID{C: "a", T: 1}, V: "y"}); err == nil {
		t.Fatal("same id with different content must be rejected")
	}
}

func TestLimits(t *testing.T) {
	d := NewDocument(Limits{MaxAtoms: 3})
	if _, err := d.InsertText("a", nil, "abc"); err != nil {
		t.Fatal(err)
	}
	if _, err := d.InsertText("a", nil, "d"); err == nil {
		t.Fatal("expected doc_too_large")
	}
	p := NewDocument(Limits{MaxPending: 1})
	if _, err := p.Apply(Op{K: "d", ID: ID{C: "x", T: 1}}); err != nil {
		t.Fatal(err)
	}
	if _, err := p.Apply(Op{K: "d", ID: ID{C: "x", T: 2}}); err == nil {
		t.Fatal("expected pending_overflow")
	}
}

func TestUnicode(t *testing.T) {
	for _, s := range []string{"😀", "e\u0301", "👩‍👩‍👧‍👦", "漢字", "🇮🇳"} {
		a := NewDocument(Limits{})
		ops, err := a.InsertText("a", nil, s)
		if err != nil {
			t.Fatal(err)
		}
		if len(ops) != len([]rune(s)) {
			t.Fatalf("%q: %d atoms, want one per code point", s, len(ops))
		}
		b := NewDocument(Limits{})
		applyAll(t, b, reversed(ops))
		if a.Text() != s || b.Text() != s {
			t.Fatalf("%q round trip failed: %q / %q", s, a.Text(), b.Text())
		}
	}
	d := NewDocument(Limits{})
	if _, err := d.InsertText("a", nil, "x\xffy"); err != nil {
		t.Fatal(err)
	}
	if d.Text() != "x\uFFFDy" {
		t.Fatalf("invalid byte not replaced: %q", d.Text())
	}
}

func TestSnapshotLateJoinAndTailText(t *testing.T) {
	a := NewDocument(Limits{})
	insertAt(t, a, "a", 0, "hello world")
	a.DeleteIDs(a.VisibleIDs()[5:11])
	late := NewDocument(Limits{})
	if _, err := late.MergeSnapshot(a.Snapshot()); err != nil {
		t.Fatal(err)
	}
	if late.Fingerprint() != a.Fingerprint() || late.Lamport() != a.Lamport() {
		t.Fatal("late joiner differs")
	}
	if got := a.TailText(3); got != "llo" {
		t.Fatalf("TailText = %q", got)
	}
}

// TestRandomConvergence: replicas edit concurrently and receive each other's
// ops in random order with duplicates; all must converge (seeded, reproducible).
func TestRandomConvergence(t *testing.T) {
	alphabet := []string{"a", "b", " ", "\n", "é", "😀"}
	for seed := int64(1); seed <= 300; seed++ {
		r := rand.New(rand.NewSource(seed))
		const n = 4
		docs := make([]*Document, n)
		inbox := make([][]Op, n)
		for i := range docs {
			docs[i] = NewDocument(Limits{})
		}
		for step := 0; step < 50; step++ {
			k := r.Intn(n)
			d := docs[k]
			var ops []Op
			if d.Len() > 0 && r.Float64() < 0.35 {
				ids := d.VisibleIDs()
				from := r.Intn(len(ids))
				to := from + 1 + r.Intn(3)
				if to > len(ids) {
					to = len(ids)
				}
				ops = d.DeleteIDs(ids[from:to])
			} else {
				var b strings.Builder
				count := 1 + r.Intn(4)
				for i := 0; i < count; i++ {
					b.WriteString(alphabet[r.Intn(len(alphabet))])
				}
				ops = insertAt(t, d, "r"+string(rune('0'+k)), r.Intn(d.Len()+1), b.String())
			}
			for j := range inbox {
				if j != k {
					inbox[j] = append(inbox[j], ops...)
				}
			}
			j := r.Intn(n)
			if len(inbox[j]) > 0 && r.Float64() < 0.6 {
				r.Shuffle(len(inbox[j]), func(a, b int) { inbox[j][a], inbox[j][b] = inbox[j][b], inbox[j][a] })
				cut := r.Intn(len(inbox[j]) + 1)
				applyAll(t, docs[j], inbox[j][:cut])
				applyAll(t, docs[j], inbox[j][:cut]) // duplicate delivery
				inbox[j] = append([]Op(nil), inbox[j][cut:]...)
			}
		}
		for j := range inbox {
			applyAll(t, docs[j], shuffled(inbox[j], seed))
		}
		fp := docs[0].Fingerprint()
		for j, d := range docs {
			if d.Fingerprint() != fp || d.Pending() != 0 {
				t.Fatalf("seed %d: replica %d diverged (pending=%d)", seed, j, d.Pending())
			}
		}
	}
}

// FuzzApply feeds arbitrary JSON op lists; Apply must never panic and the
// document must stay internally consistent.
func FuzzApply(f *testing.F) {
	f.Add([]byte(`[{"k":"i","id":{"c":"a","t":1},"o":null,"v":"x"},{"k":"d","id":{"c":"a","t":1}}]`))
	f.Add([]byte(`[{"k":"i","id":{"c":"a","t":2},"o":{"c":"b","t":1},"v":"😀"}]`))
	f.Add([]byte(`[{"k":"i","id":{"c":"a","t":1},"o":null,"v":"ab"}]`))
	f.Fuzz(func(t *testing.T, data []byte) {
		var ops []Op
		if json.Unmarshal(data, &ops) != nil || len(ops) > 500 {
			return
		}
		d := NewDocument(Limits{MaxAtoms: 1000, MaxPending: 1000})
		for _, op := range ops {
			_, _ = d.Apply(op)
		}
		if got := len([]rune(d.Text())); got != d.Len() {
			t.Fatalf("visible count %d != text length %d", d.Len(), got)
		}
		if d.Pending() == 0 {
			c := NewDocument(Limits{})
			if _, err := c.MergeSnapshot(d.Snapshot()); err != nil {
				t.Fatalf("snapshot not mergeable: %v", err)
			}
			if c.Fingerprint() != d.Fingerprint() {
				t.Fatal("snapshot round trip changed state")
			}
		}
	})
}

func BenchmarkSequentialTyping(b *testing.B) {
	for i := 0; i < b.N; i++ {
		d := NewDocument(Limits{})
		var last *ID
		for j := 0; j < 10000; j++ {
			ops, _ := d.InsertText("bench", last, "x")
			id := ops[0].ID
			last = &id
		}
	}
}

func BenchmarkApplyRemoteRandomPositions(b *testing.B) {
	src := NewDocument(Limits{})
	r := rand.New(rand.NewSource(1))
	var ops []Op
	for j := 0; j < 5000; j++ {
		var after *ID
		if src.Len() > 0 {
			ids := src.VisibleIDs()
			id := ids[r.Intn(len(ids))]
			after = &id
		}
		o, _ := src.InsertText("src", after, "y")
		ops = append(ops, o...)
	}
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		d := NewDocument(Limits{})
		for _, op := range ops {
			_, _ = d.Apply(op)
		}
	}
}
